const key='streakfit-v1';
const dateKey=()=>new Date().toLocaleDateString('en-CA');
let state;try{state=JSON.parse(localStorage.getItem(key))||{};}catch{state={};}
state.profile ||= {name:'新朋友',goal:'建立运动习惯',days:'3',place:'家中 · 无器械',minutes:'15'};
state.history ||= {};state.history[dateKey()] ||= {water:0,protein:false,vegetables:false,sleep:0,sets:{},rest:false};
const today=()=>state.history[dateKey()] ||= {water:0,protein:false,vegetables:false,sleep:0,sets:{},rest:false};
let selectedWorkoutDate=null;
function workoutDateKey(){return selectedWorkoutDate||dateKey();}
function workoutDate(){return new Date(workoutDateKey()+'T12:00:00');}
function isPreview(){return workoutDateKey()!==dateKey();}
function workoutDay(){const date=workoutDateKey();state.plannedWorkouts ||= {};if(date!==dateKey())return state.plannedWorkouts[date] ||= {water:0,protein:false,vegetables:false,sleep:0,sets:{},rest:false,planGoal:state.profile.goal};const d=today(),draft=state.plannedWorkouts[date];if(draft&&!Object.values(d.logs||{}).some(sets=>sets.length)){for(const key of ['exerciseIds','workoutTitle','targets','cardioTargets','sessionEntries','cycle','mobilityTargets','trainingPreferences','manualOrder'])if(draft[key]!==undefined)d[key]=draft[key];delete state.plannedWorkouts[date];}return d;}
function openWorkoutDay(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T12:00:00')))return false;selectedWorkoutDate=date;page='workout';render();return true;}
function selectedPrescription(){const plan=prescription(workoutDate());if(isPreview()&&schedule(workoutDate())!=='training')return {...plan,ids:[],entries:[],targets:{},durations:undefined,sets:0,title:'恢复日 · 轻松活动',note:'这一天原计划为恢复日，可以提前添加轻松活动，不要求完成力量训练。'};return plan;}
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moves=[['椅子深蹲','🪑','双脚与肩同宽；髋部向后坐；膝盖朝脚尖方向。'],['墙壁俯卧撑','🙌','双手撑墙；身体保持直线；缓慢屈肘再推回。'],['臀桥','〰','仰卧屈膝；脚掌贴地；抬髋时避免腰部过度后仰。']];
const trained=d=>d.exerciseIds ? d.exerciseIds.length>0&&d.exerciseIds.every(id=>catalog[id]?.mobility?(d.logs?.[id]||[]).filter(l=>l.mobilitySets).length>=(d.mobilityTargets?.[id]||2):catalog[id]?.kind==='cardio'?(d.logs?.[id]||[]).reduce((sum,l)=>sum+(l.minutes||0),0)>=cardioTarget(id,d):(d.logs?.[id]?.length||0)>=(exerciseTarget(id,d).sets)) : moves.every((_,i)=>(d.sets?.[i]||0)>=2);
const points=d=>(trained(d)||d.rest?30:0)+(d.protein&&d.vegetables?20:0)+(d.water>=8?15:0)+(d.sleep>=(d.sleepTarget||7)?15:0)+((trained(d)||d.rest)&&d.protein&&d.vegetables&&d.water>=8&&d.sleep>=(d.sleepTarget||7)?20:0);
const total=()=>Object.values(state.history).reduce((a,d)=>a+points(d),0);
function streak(){let n=0,d=new Date();if(points(today())===0)d.setDate(d.getDate()-1);for(;n<10000;n++){if(!points(state.history[d.toLocaleDateString('en-CA')]||{sets:{}}))break;d.setDate(d.getDate()-1);}return n;}
