function rotatedSlots(title,at){const base=sessionSlots[title];if(!base)return null;const exposure=cycleContext(at).exposure;const variant=(state.profile.experience==='初学者'?Math.floor(exposure/2):exposure)%2;const slots=base.map(slot=>({...slot,options:[...slot.options]}));
 if(title==='上肢力量'){slots[2].options=variant?['fly','bandfly','incline','dbpress']:['incline','fly','bandfly','dbpress'];slots[4].options=variant?['lateral','wallslide']:['shoulderpress','lateral','wallslide'];slots[4].label=variant?'肩外展 · 侧束重点':'垂直推 · 前束重点';if(variant)slots[3].options=['cablerow','row','bandrow','proneW'];}
 if(title==='推 · 胸肩三头'){const chest=slots.splice(5,1)[0];slots.splice(2,0,chest);const shoulder=slots.find(slot=>slot.label==='垂直推 · 肩部主项');shoulder.options=variant?['lateral','wallslide']:['shoulderpress','lateral','wallslide'];shoulder.label=variant?'肩外展 · 侧束重点':'垂直推 · 前束重点';const extra=slots.findIndex(slot=>slot.label==='肩外展 · 侧束');slots.splice(extra,1);}
 if(variant){for(const slot of slots){if(slot.options[0]==='curl')slot.options=['hammer','curl','bandcurl','selfcurl'];if(slot.options[0]==='deadbug')slot.options=['bird','deadbug'];if(slot.options[0]==='goblet')slot.options=['legpress','goblet','squat'];}}
 // Keep the strength main lift stable; vary compatible hypertrophy presses.
 if(variant&&state.profile.goal==='增肌与体型塑造'&&state.profile.experience!=='初学者'){const press=slots.find(slot=>slot.options[0]==='bench');if(press)press.options=['dbbench','bench','dbpress','push'];}
 const focus=state.profile.muscleFocus;
 if(title==='上肢力量'&&['chest','back'].includes(focus)){const extra=focus==='chest'?{label:'胸部重点 · 第三动作',options:['fly','incline','dbpress','bandfly'],rest:90}:{label:'背部重点 · 第三动作',options:['cablerow','row','bandrow','proneW'],rest:90};slots.splice(3,0,extra);if(focus==='back'){const pull=slots.splice(1,1)[0];slots.unshift(pull);const second=slots.findIndex(x=>x.label==='水平拉 · 背部辅助');slots.splice(2,0,slots.splice(second,1)[0]);}}
 const prioritized=focusMuscles[focus];if(prioritized&&focus!=='chest'&&focus!=='back')slots.sort((a,b)=>Number(b.options.some(id=>catalog[id]?.muscle===prioritized))-Number(a.options.some(id=>catalog[id]?.muscle===prioritized)));
 return slots;}
function requestedCount(){const n=Number(state.profile.exerciseCount);return Number.isInteger(n)&&n>=1&&n<=12?n:null;}
function fullBodySlots(at){const groups=['胸部','背部','股四头肌','腘绳肌','臀部','核心','肩部','肱二头肌','肱三头肌','小腿'];if(state.profile.muscleFocus==='back')[groups[0],groups[1]]=[groups[1],groups[0]];const slots=groups.map(m=>({label:m+' · 全身训练',options:[...groupChoices[m]],rest:90}));const muscle=state.profile.muscleFocus==='chest'?'胸部':state.profile.muscleFocus==='back'?'背部':null;if(muscle)slots.splice(4,0,{label:muscle+' · 重点辅助',options:muscle==='胸部'?['incline','fly','dbbench','dbpress','bandfly','push']:['cablerow','row','pulldown','bandrow','proneW'],rest:90});const prioritized=focusMuscles[state.profile.muscleFocus];if(prioritized)slots.sort((a,b)=>Number(b.options.some(id=>catalog[id]?.muscle===prioritized))-Number(a.options.some(id=>catalog[id]?.muscle===prioritized)));return slots;}
function templateSession(title,gear,minutes,limit,at){const slots=title==='全身力量'&&(requestedCount()||focusMuscles[state.profile.muscleFocus])?fullBodySlots(at):rotatedSlots(title,at);if(!slots)return null;const budget=Math.max(0,minutes-10);const maxMoves=state.profile.experience==='初学者'?Math.min(limit,5):limit;const used=new Set(),entries=[];let estimated=10;for(const slot of slots){let id=slot.options.find(id=>supports(id,gear)&&!used.has(id));if(!id)continue;const preferred=state.exerciseReplacements?.[id];if(preferred&&catalog[preferred]?.muscle===catalog[id].muscle&&supports(preferred,gear)&&!used.has(preferred))id=preferred;const sets=state.exerciseTargets?.[id]?.sets||4;const cost=(sets*40+(sets-1)*slot.rest+90)/60;if(entries.length>=maxMoves||estimated-10+cost>budget)continue;entries.push({id,label:slot.label,rest:slot.rest,sets});used.add(id);estimated+=cost;}return {ids:entries.map(e=>e.id),entries,estimated:Math.ceil(estimated),sets:4,title};}
