function cardioPlan(){const p=state.profile,gear=selectedEquipment();const main=['treadmill','bike','elliptical','rowing'].find(id=>supports(id,gear))||(p.place==='户外 / 公园'?'briskwalk':'march');const available=Number(p.minutes)||15;const cap=p.experience==='有规律训练经验'?60:30;const duration=Math.min(available,cap);const warm=duration<=15?2:5,cool=warm;return {title:'心肺耐力 · 稳态训练',ids:['warmwalk',main,'cooldown'],sets:0,durations:{warmwalk:warm,[main]:duration-warm-cool,cooldown:cool},estimated:duration};}
function cardioTarget(id,d=workoutDay()){return d.cardioTargets?.[id]||selectedPrescription().durations?.[id]||15;}
function mobilityCard(id,d){const m=catalog[id],target=d.mobilityTargets?.[id]||2,logs=d.logs?.[id]||[],done=logs.filter(l=>l.mobilitySets).length;return `<section class="card workout-card"><button data-lesson="${id}"><h3>${esc(m.name)} ▷</h3></button><button class="remove-exercise" data-remove-exercise="${id}">移除此动作</button>${orderControls(id)}<p>${target} 组 · ${esc(m.dose||'每侧 6–8 次，缓慢控制')} · 组间轻松休息 20–30 秒</p><p>保持无痛范围，不以心率或“中等强度”衡量。已记录 ${done} / ${target} 组</p><label>目标组数（可调整）<input id="mobility-target-${id}" type="number" min="1" max="5" value="${target}"></label><button data-save-mobility="${id}">保存目标</button><button class="primary" data-log-mobility="${id}" ${isPreview()||done>=target?'disabled':''}>完成一组</button><button data-remove-log="${id}" ${isPreview()?'disabled':''}>撤回</button>${logs.filter(l=>l.mobilitySets).map(()=>'<p class="set-row">✓ 一组活动度练习</p>').join('')}<p id="mobility-feedback-${id}" class="muted"></p></section>`;}
function cardioCard(id,d,plan){if(catalog[id].mobility)return mobilityCard(id,d);const m=catalog[id],target=cardioTarget(id,d),logs=d.logs?.[id]||[],done=logs.reduce((sum,l)=>sum+(l.minutes||0),0);return `<section class="card workout-card"><button data-lesson="${id}"><h3>${esc(m.name)} ▷</h3></button><button class="remove-exercise" data-remove-exercise="${id}">移除此动作</button>${orderControls(id)}<p>建议 ${target} 分钟 · ${m.intensity|| (id==='warmwalk'||id==='cooldown'?'轻松，RPE 2–3 / 10':'中等强度，RPE 4–6 / 10；能说完整句子')}</p><p>已记录 ${done} / ${target} 分钟</p><div class="set-input"><label>本次完成分钟<input id="cardio-minutes-${id}" type="number" min="1" max="180" value="${Math.max(1,target-done)}"></label><label>目标分钟（可自定义）<input id="cardio-target-${id}" type="number" min="1" max="180" value="${target}"></label><label>实际强度<select id="cardio-effort-${id}"><option ${id==='warmwalk'||id==='cooldown'?'selected':''}>轻松</option><option ${id==='warmwalk'||id==='cooldown'?'':'selected'}>中等</option><option>较吃力</option></select></label></div><button class="primary" data-log-cardio="${id}" ${isPreview()?'disabled':''}>记录时长</button> <button data-save-cardio="${id}">保存目标</button> <button data-remove-log="${id}" ${isPreview()?'disabled':''}>撤回上次记录</button>${logs.map(l=>`<p class="set-row">✓ ${l.minutes} 分钟 · ${esc(l.effort||'中等')}</p>`).join('')}<p id="cardio-feedback-${id}" class="muted"></p></section>`;}
