const strengthMainIds=new Set(['barsquat','frontsquat','barohp','smithbench','inclinebar','barRdl','barhip','barrow','bench','dbbench','dbpress','incline','push','row','cablerow','pulldown','goblet','squat','legpress','rdl','deadlift','hipthrust','shoulderpress']);
function defaultExerciseTarget(id){const target=goalTarget();return state.profile.goal==='提升力量'&&!strengthMainIds.has(id)?{sets:target.sets,min:8,max:12}:target;}
function goalTarget(){const rule=goalRules[state.profile.goal];if(!rule)return {sets:4,min:8,max:12};if(state.profile.goal==='提升力量'&&state.profile.experience!=='有规律训练经验')return {sets:rule.sets,min:6,max:8};return {sets:rule.sets,min:rule.min,max:rule.max};}
function cyclePanel(c){if(!c)return '';return `<div class="card cycle-panel"><p class="eyebrow">4 WEEK TRAINING BLOCK</p><h3>第 ${c.week} 周 · ${esc(c.phase)}${state.profile.goal==='提升力量'?' / '+esc(c.session):''}</h3><div class="week">${['基础积累','渐进建立','巩固表现','减量恢复'].map((name,i)=>`<div class="day"><div class="dot ${c.blockWeek===i+1?'done':''}">${i+1}</div>${name}</div>`).join('')}</div><p class="muted">RIR = 做完后估计还能完成的次数。手动目标优先，减量周不覆盖你的自定义。</p><p class="muted">周期方法原型 · 非职业选手原版训练表；参考资料待核验。</p></div>`;}
function cycleContext(at=new Date()){
 const elapsed=Math.max(0,dayIndex(at)-dayIndex(anchorDate()));const week=Math.floor(elapsed/7)+1,blockWeek=(week-1)%4+1;
 const split=state.profile.split;const effectiveDays=state.profile.scheduleMode==='weekly'?weeklyDays().length:state.profile.scheduleMode==='cycle'?7*(Number(state.profile.trainDays)||3)/((Number(state.profile.trainDays)||3)+(Number(state.profile.restDays)||1)):Number(state.profile.days)||3;
 const patternLength=split==='ppl'?3:split==='upperlower'?2:split==='full'?1:effectiveDays<=3?1:effectiveDays<=4?2:3;
 const exposure=Math.floor(trainingOrdinal(at)/patternLength);const beginner=state.profile.experience==='初学者';
 const session=beginner?'技术适应':['重训练','训练量','技术轻练'][exposure%3];
 return {week,blockWeek,phase:['基础积累','渐进建立','巩固表现','减量恢复'][blockWeek-1],deload:blockWeek===4,session,exposure};
}
function periodizePlan(base,at){
 const p=state.profile,c=cycleContext(at),time=Number(p.minutes)||15,goal=p.goal;const result={...base,cycle:c,targets:{},durations:{...(base.durations||{})},entries:[],note:base.note||''};
 let elapsed=Math.min(5,time*.2);const ids=[];
 for(const id of base.ids){const timed=catalog[id].kind==='cardio';if(timed){let duration=base.durations?.[id]||15;if(goal==='提升心肺与耐力'){if(id!=='warmwalk'&&id!=='cooldown'){const baseMain=duration;duration=c.deload?Math.max(1,Math.floor(baseMain*.65)):Math.min(baseMain+Math.max(0,c.blockWeek-1)*2,Math.max(1,time-(base.durations.warmwalk||0)-(base.durations.cooldown||0)));}}else if(c.deload&&goal!=='灵活性与日常活动能力')duration=Math.max(1,Math.floor(duration*.7));result.durations[id]=duration;ids.push(id);continue;}
 let target={...(base.targets?.[id]||defaultExerciseTarget(id))},rest=base.entries?.find(e=>e.id===id)?.rest||90;const main=base.specialtyMain?id===base.specialtyMain:strengthMainIds.has(id);
 if(goal==='提升力量'&&main){if(p.experience==='初学者'){target={sets:3,min:6,max:8};rest=120;}else if(c.session==='重训练'){target={sets:4,min:4,max:6};rest=180;}else if(c.session==='训练量'){target={sets:4,min:6,max:8};rest=150;}else{target={sets:3,min:6,max:8};rest=90;}}
 if(c.deload&&['提升力量','增肌与体型塑造','减脂与体重管理'].includes(goal)){target.sets=Math.max(1,Math.ceil(target.sets*.5));}
 target.rir=goal==='增肌与体型塑造'?(c.deload?4:4-c.blockWeek):goal==='提升力量'?(c.deload||c.session==='技术轻练'||p.experience==='初学者'?4:2):3;
 const custom=state.exerciseTargets?.[id];if(custom)target={...target,...custom};
 const cost=(target.sets*35+(target.sets-1)*rest+60)/60;
 const cardioBudget=base.ids.filter(x=>catalog[x].kind==='cardio').reduce((n,x)=>n+(base.durations?.[x]||0),0);
 if(ids.filter(x=>catalog[x].kind!=='cardio').length&&elapsed+cost>time-cardioBudget)continue;
 let actualCost=cost;if(elapsed+cost>time-cardioBudget){if(custom){target.timeWarning=true;}else{const fitting=Math.floor(((time-cardioBudget-elapsed)*60-60+rest)/(35+rest));target.sets=Math.max(1,Math.min(target.sets,fitting));actualCost=(target.sets*35+(target.sets-1)*rest+60)/60;target.timeAdjusted=true;}}
 ids.push(id);elapsed+=actualCost;result.targets[id]=target;result.entries.push({id,sets:target.sets,rest,label:base.entries?.find(e=>e.id===id)?.label||catalog[id].muscle});
 }
 result.ids=ids;const timedTotal=ids.filter(id=>catalog[id].kind==='cardio').reduce((n,id)=>n+result.durations[id],0);result.estimated=Math.ceil((ids.every(id=>catalog[id].kind==='cardio')?0:elapsed)+timedTotal);
 if(!ids.some(id=>catalog[id].kind==='cardio'))delete result.durations;
 const rule=goal==='提升力量'?`${c.deload?'减量恢复':c.session}：主项与辅助项分别设置，负重以保留次数控制。`:goal==='增肌与体型塑造'?`本周保留约 ${c.deload?4:4-c.blockWeek} 次余力；减量周降低推荐组数，动作不要求力竭。`:goal==='提升心肺与耐力'?'稳态耐力递进；尚未加入可验证的间歇/阈值测试，强度以谈话测试控制。':goal==='减脂与体重管理'?'保持力量训练与有氧，第四周降低训练量，不自动扩大热量缺口。':'';
 result.preferenceNote=goalRules[goal]?`力量偏好：${liftDayNames[p.muscleFocus]|| (focusMuscles[p.muscleFocus]?focusMuscles[p.muscleFocus]+'专项':'均衡')} · ${requestedCount()?'希望 '+requestedCount()+' 个力量动作，实际 '+ids.filter(id=>catalog[id].kind!=='cardio').length+' 个。数量受当前训练分配、时间、经验与器械限制。':'动作数量自动推荐。'}`:'';result.note=[base.note,rule].filter(Boolean).join(' ');return result;
}
const liftDayNames={deadlift_day:'硬拉日',squat_day:'深蹲日',bench_day:'卧推日'};
const focusMuscles={chest:'胸部',back:'背部',shoulders:'肩部',biceps:'肱二头肌',triceps:'肱三头肌',quadriceps:'股四头肌',hamstrings:'腘绳肌',glutes:'臀部',calves:'小腿',core:'核心',arms:'手臂'};
function focusOptions(at=workoutDate()){const savedFocus=state.profile.muscleFocus;state.profile.muscleFocus='balanced';let title;try{title=strengthPrescription(at).title;}finally{state.profile.muscleFocus=savedFocus;}const keys=title==='下肢 + 核心'||title==='腿 · 臀腿核心'?['quadriceps','hamstrings','glutes','calves','core']:title==='推 · 胸肩三头'?['chest','shoulders','triceps','arms']:title==='拉 · 背部二头'?['back','biceps','arms']:title==='上肢力量'?['chest','back','shoulders','biceps','triceps','arms']:Object.keys(focusMuscles);return [['balanced','均衡'],...keys.filter(key=>!['biceps','triceps'].includes(key)).map(key=>[key,focusMuscles[key]+'专项']),...(state.profile.goal==='提升力量'?Object.entries(liftDayNames):[])];}
