function exerciseOrderRank(id){const order=muscleExerciseOrder[catalog[id]?.muscle]||[];const rank=order.indexOf(id);return rank<0?order.length:rank;}
function exerciseOrderNote(id){if(['hammer','ropehammer'].includes(id))return '后段辅助：中立握弯举；先完成本次安排的常规弯举。';if(['fly','dbfly','pecdeck','bandfly','legextension','legcurl','cablekick','abduction'].includes(id))return '孤立辅助：安排在同肌群主要复合动作之后。';if(['reversefly','rearpec','facepull'].includes(id))return '肩后侧辅助：安排在本次肩部主项之后。';return '';}
function orderWorkoutIds(ids,prefs={}){if(liftDayNames[prefs.muscleFocus]&&ids.length)return [ids[0],...orderWorkoutIds(ids.slice(1),{})];const groups=[...new Set(ids.filter(id=>catalog[id]?.kind!=='cardio').map(id=>catalog[id]?.muscle))];if(!groups.length)return [...ids];const focus=focusMuscles[prefs.muscleFocus]||null;if(focus&&groups.includes(focus)){groups.splice(groups.indexOf(focus),1);groups.unshift(focus);}return [...ids].sort((a,b)=>{const rank=id=>catalog[id]?.kind==='cardio'?(id==='warmwalk'?-1:groups.length):groups.indexOf(catalog[id]?.muscle);return rank(a)-rank(b)||(catalog[a]?.kind!=='cardio'&&catalog[b]?.kind!=='cardio'?exerciseOrderRank(a)-exerciseOrderRank(b):0);});}
function orderPlan(plan,prefs){const ids=orderWorkoutIds(plan.ids,prefs);return {...plan,ids,...(plan.entries?{entries:[...plan.entries].sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id))}:{})};}
function prescription(at=new Date()){const original=state.profile,date=at.toLocaleDateString('en-CA'),prefs=state.history[date]?.trainingPreferences||state.plannedWorkouts?.[date]?.trainingPreferences||{};state.profile={...original,muscleFocus:validDailyFocus(prefs.muscleFocus,at),exerciseCount:prefs.exerciseCount||'auto'};try{const base=basePrescription(at);return orderPlan(state.profile.goal?periodizePlan(base,at):base,prefs);}finally{state.profile=original;}}
function dailyPreferencePanel(d){if(!goalRules[state.profile.goal])return '';const prefs=d.trainingPreferences||{};return `<section class="card"><h3>这一天想怎么练？</h3><p>只调整 ${workoutDateKey()}，其他日期保持各自安排。部位专项只安排该部位；力量专项安排主项及相关辅助。其他动作可在下方手动添加。已记录的动作和组会保留。</p><div class="library-filters"><label>当天训练部位<select id="daily-focus">${focusOptions().map(([v,label])=>`<option value="${v}" ${validDailyFocus(prefs.muscleFocus,workoutDate())===v?'selected':''}>${label}</option>`).join('')}</select></label><label>希望的力量动作数量<select id="daily-count"><option value="auto">自动推荐</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(prefs.exerciseCount)===String(i+1)?'selected':''}>${i+1} 个动作</option>`).join('')}</select></label></div><button class="primary" data-apply-daily>应用到这一天的训练</button><p id="daily-feedback" class="muted">受时长、经验和器械限制时，实际数量可能少于期望；手动加减动作仍可使用。</p></section>`;}
function applyDailyPreferences(focus,count){if(!focusOptions().some(([key])=>key===focus)||!(count==='auto'||Number.isInteger(Number(count))&&Number(count)>=1&&Number(count)<=12))return false;const d=workoutDay();delete d.manualOrder;d.trainingPreferences={muscleFocus:focus,exerciseCount:String(count)};const plan=selectedPrescription();const recorded=Object.keys(d.logs||{}).filter(id=>catalog[id]&&d.logs[id].length);d.exerciseIds=[...new Set([...plan.ids,...recorded])];d.workoutTitle=plan.title;d.cycle=plan.cycle;d.sessionEntries=plan.entries;save();render();return true;}

function basePrescription(at=new Date()){
 const p=state.profile;if(p.goal==='提升心肺与耐力')return cardioPlan();
 if(p.goal==='灵活性与日常活动能力'){const time=Number(p.minutes)||15;const count=time<15?4:time<30?5:7;const ids=['thoracic','shoulderMob','hipmob','ankle','hamStretch','hipFlexor','calfStretch'].slice(0,count);return {title:'全身活动度 · 动态控制与伸展',ids,durations:Object.fromEntries(ids.map(id=>[id,2])),sets:2,estimated:ids.length*2,note:'动态活动每侧 6–8 次；静态伸展每侧 20–30 秒，默认各 2 组。覆盖上肢、脊柱、髋、腿与踝；不要求把可用时间练满。'};}
 let plan=strengthPrescription(at);const rule=goalRules[p.goal];if(!rule)return plan;
 const time=Number(p.minutes)||15,shortGoal=['建立运动习惯','保持健康与精力'].includes(p.goal),mixed=['减脂与体重管理','保持健康与精力'].includes(p.goal);
 const countLimit=Math.min(requestedCount()||12,shortGoal?3:p.experience==='初学者'?5:12);
 let strengthBudget=shortGoal?Math.min(time,30):time;
 const cardioDuration=mixed&&p.muscleFocus==='balanced'&&time>=20?Math.min(20,Math.max(5,Math.floor(time*.3))):0;strengthBudget-=cardioDuration;
 let estimated=Math.min(5,Math.max(1,strengthBudget*.2));const selected=[],entries=[];
 for(const id of plan.ids){if(selected.length>=countLimit)break;const target=state.exerciseTargets?.[id]||(plan.specialtyMain&&id!==plan.specialtyMain?{sets:3,min:8,max:12}:defaultExerciseTarget(id));const rest=p.goal==='提升力量'?(plan.specialtyMain?(id===plan.specialtyMain?rule.rest:plan.entries.find(e=>e.id===id)?.rest||90):(strengthMainIds.has(id)?rule.rest:90)):(plan.entries?.find(e=>e.id===id)?.rest||rule.rest);const cost=(target.sets*35+(target.sets-1)*rest+60)/60;if(plan.specialtyMain===id&&estimated+cost>strengthBudget){selected.push(id);entries.push({id,sets:target.sets,rest,label:plan.entries.find(e=>e.id===id)?.label||catalog[id].muscle});estimated=strengthBudget;break;}if(estimated+cost>strengthBudget&&selected.length>0)break;if(estimated+cost>strengthBudget)continue;selected.push(id);estimated+=cost;entries.push({id,sets:target.sets,rest,label:plan.entries?.find(e=>e.id===id)?.label||catalog[id].muscle});}
 if(!selected.length&&time>=10&&plan.ids.length){const id=plan.ids[0];selected.push(id);entries.push({id,sets:rule.sets,rest:rule.rest,label:catalog[id].muscle});estimated=Math.min(time,8);}
 const durations={};if(cardioDuration){const id=cardioPlan().ids[1];selected.push(id);durations[id]=cardioDuration;estimated+=cardioDuration;}
 return {...plan,title:p.goal==='建立运动习惯'?'习惯起步 · 短时基础':p.goal==='保持健康与精力'?'健康活动 · 力量与有氧':p.goal==='减脂与体重管理'?'体重管理 · 力量与有氧':p.goal==='提升力量'?plan.title+' · 力量重点':plan.title+' · 增肌重点',ids:selected,entries,targets:plan.specialtyMain?Object.fromEntries(selected.map(id=>[id,state.exerciseTargets?.[id]||(id===plan.specialtyMain?defaultExerciseTarget(id):{sets:3,min:8,max:12})])):plan.targets,sets:rule.sets,durations:Object.keys(durations).length?durations:undefined,estimated:Math.ceil(estimated),note:[rule.note,plan.note].filter(Boolean).join(' '),selectionInfo:plan.ids.length<6?'器械与当前训练分配限制了候选动作；请核对已勾选的器械。':selected.filter(id=>catalog[id].kind!=='cardio').length<plan.ids.length?'已按经验上限或组间休息预算缩减动作。':'已按当前器械、经验和时间预算选择动作。'};
}
function liftDaySession(){const focus=state.profile.muscleFocus,gear=selectedEquipment();const definitions={deadlift_day:{main:['deadlift','barRdl','rdl','hinge'],aux:[{label:'腿后侧 · 屈膝辅助',options:['legcurl']},{label:'臀部 · 锁定阶段辅助',options:['barhip','hipthrust','bridge']},{label:'上背稳定',options:['chestsupported','cablerow','row','bandrow','proneW']},{label:'髋铰链辅助',options:['rdl','barRdl','hinge']},{label:'核心稳定',options:['deadbug','bird']}]},squat_day:{main:['barsquat','goblet','squat'],aux:[{label:'单腿稳定',options:['bulgarian','lunge']},{label:'膝伸辅助',options:['legpress','legextension']},{label:'后侧链辅助',options:['legcurl','rdl','hinge']},{label:'核心稳定',options:['deadbug','bird']}]},bench_day:{main:['bench','dbbench','dbpress','push'],aux:[{label:'胸部辅助',options:['incline','chestmachine','pushup']},{label:'肘伸 · 三头辅助',options:['triceps','ropepush','dbtriceps','closepush']},{label:'上背与肩胛稳定',options:['chestsupported','cablerow','row','proneW']},{label:'肩后侧辅助',options:['facepull','reversefly']},{label:'核心稳定',options:['deadbug','bird']}]}};const definition=definitions[focus],main=definition.main.find(id=>supports(id,gear));const entries=main?[{id:main,label:'主项 · '+catalog[main].name,rest:180}]:[],used=new Set(main?[main]:[]);for(const slot of definition.aux){const id=slot.options.find(id=>supports(id,gear)&&!used.has(id));if(id){entries.push({id,label:slot.label,rest:slot.label==='髋铰链辅助'?120:90});used.add(id);}}const count=requestedCount()||6;const selected=entries.slice(0,state.profile.experience==='初学者'?Math.min(count,5):count);return {title:liftDayNames[focus]+(main!==definition.main[0]?' · 基础替代':''),ids:selected.map(e=>e.id),entries:selected,sets:4,specialtyMain:main,note:'先完成主项，再完成相关辅助；不把每个辅助动作都当成重主项。'+(main!==definition.main[0]?'当前器械或经验不满足原主项要求，已显示可用的基础替代动作。':'')};}
function isolatedSession(at){const focus=state.profile.muscleFocus,muscles=focus==='arms'?['肱二头肌','肱三头肌']:[focusMuscles[focus]];const gear=selectedEquipment();let ids=muscles.flatMap(m=>{const preferred={胸部:['bench','incline','fly','dbbench','chestmachine','pecdeck','smithbench','dbfly','dbpress','pushup','push'],肱二头肌:['curl','hammer','cablecurl','preacher','altcurl','inclinecurl','concentration','barcurl','ropehammer','dbpreacher'],肱三头肌:['triceps','overheadtriceps','skullcrusher','ropepush','cableoverhead','closebench','dbtriceps','closepush']};const primary=preferred[m]||groupChoices[m]||[];return [...new Set([...primary,...Object.keys(catalog).filter(id=>catalog[id].muscle===m&&catalog[id].kind!=='cardio')])].filter(id=>supports(id,gear));});if(focus==='arms'){const a=ids.filter(id=>catalog[id].muscle==='肱二头肌'),b=ids.filter(id=>catalog[id].muscle==='肱三头肌');ids=Array.from({length:Math.max(a.length,b.length)},(_,i)=>[a[i],b[i]]).flat().filter(Boolean);}const limit=requestedCount()||Math.min(6,Math.max(1,Math.floor(Number(state.profile.minutes)/10)));ids=ids.slice(0,state.profile.experience==='初学者'?Math.min(limit,5):limit);return {title:focusMuscles[focus]+'专项',ids,sets:4,entries:ids.map(id=>({id,rest:strengthMainIds.has(id)?120:90,label:catalog[id].muscle+' · 专项动作'}))};}
function strengthPrescription(at=new Date()){if(state.profile.goal==='提升心肺与耐力')return cardioPlan();const p=state.profile;if(p.goal==='提升力量'&&liftDayNames[p.muscleFocus])return liftDaySession();if(focusMuscles[p.muscleFocus])return isolatedSession(at);const gear=selectedEquipment(p),days=p.scheduleMode==='cycle'?7*Number(p.trainDays)/(Number(p.trainDays)+Number(p.restDays)):p.scheduleMode==='weekly'?weeklyDays().length:Number(p.days)||3;const ordinal=trainingOrdinal(at);let groups,title;if(p.split==='full'||((!p.split||p.split==='auto')&&days<=3)){groups=['胸部','背部','股四头肌','腘绳肌','臀部','核心','肩部','肱二头肌','肱三头肌','小腿'];title='全身力量';}else if(p.split==='upperlower'||((!p.split||p.split==='auto')&&days<=4)){groups=ordinal%2===0?['胸部','背部','肩部','肱二头肌','肱三头肌']:['股四头肌','腘绳肌','臀部','小腿','核心'];title=ordinal%2===0?'上肢力量':'下肢 + 核心';}else{const splits=[['胸部','肩部','肱三头肌','核心'],['背部','肱二头肌','肩部','核心'],['股四头肌','腘绳肌','臀部','小腿','核心']];groups=splits[ordinal%3];title=['推 · 胸肩三头','拉 · 背部二头','腿 · 臀腿核心'][ordinal%3];}const minutes=Number(p.minutes)||15;const limit=requestedCount()||(minutes<30?2:minutes<45?4:minutes<=60?6:minutes<=90?8:10);if((p.split==='full'||((!p.split||p.split==='auto')&&days<=3))&&limit<10){const essentials=groups.slice(0,2);const accessories=groups.slice(2);groups=[...essentials,...accessories.slice((ordinal*2)%accessories.length),...accessories.slice(0,(ordinal*2)%accessories.length)];}const template=templateSession(title,gear,minutes,limit,at);if(template?.ids.length)return template;const ids=groups.slice(0,limit).map(group=>(()=>{const options=[...groupChoices[group]];const exposure=cycleContext(at).exposure;if(exposure%2&&p.goal&&['有一些经验 / 重新开始','有规律训练经验'].includes(p.experience)&&!(p.goal==='提升力量'&&group==='胸部'))options.push(options.shift());return options.find(id=>supports(id,gear));})()).map(id=>{const preferred=state.exerciseReplacements?.[id];return preferred&&catalog[preferred]?.muscle===catalog[id].muscle&&supports(preferred,gear)?preferred:id;});return {ids,sets:4,title};}

function equipmentSummary(){return selectedEquipment().join('、')||'徒手训练';}
function equipmentMarkup(place,selected=[]){return equipmentOptions(place).map(item=>`<label class="equipment-choice"><input type="checkbox" name="equipment" value="${esc(item)}" ${selected.includes(item)?'checked':''}><span>${esc(item)}</span></label>`).join('');}
function refreshEquipment(place,selected=[]){document.querySelector('#equipment-options').innerHTML=equipmentMarkup(place,selected);document.querySelector('#equipment-note').innerHTML='未选择器械时按徒手训练。新设备已可记录；动作库覆盖主要肌群，计划只选用你具备器械的动作。杠铃硬拉仅供有规律训练经验且具备杠铃和硬拉台的用户。';}

function previous(id){return Object.entries(state.history).filter(([day,d])=>day<workoutDateKey()&&d.logs?.[id]?.length).sort(([a],[b])=>b.localeCompare(a))[0];}
function sessionSummary(ids,d,plan){if(ids.length&&ids.every(id=>catalog[id].kind==='cardio')&&ids.every(id=>catalog[id].muscle==='活动度'))return `<div class="card"><h3>活动度专项</h3><p>覆盖肩、胸椎、髋、腿与踝 · 按组练习，记录每侧次数或保持秒数。</p></div>`;if(ids.length&&ids.every(id=>catalog[id].kind==='cardio'))return `<div class="card"><p class="eyebrow">CARDIO SESSION</p><p>热身 → 稳态心肺 → 放松 · 建议共 ${ids.reduce((sum,id)=>sum+cardioTarget(id,d),0)} 分钟</p><p>可用时间是上限，不自动要求 120 分钟有氧。先建立可持续时长，再根据恢复逐步调整。出现胸痛、眩晕或异常气促时停止。</p></div>`;const volume={};for(const id of ids){if(catalog[id].kind==='cardio')continue;const muscle=catalog[id].muscle;volume[muscle] ||= {moves:0,sets:0};volume[muscle].moves++;volume[muscle].sets+=exerciseTarget(id,d).sets;}return `<div class="card"><p class="eyebrow">SESSION STRUCTURE</p><p>${Object.entries(volume).map(([muscle,v])=>`${esc(muscle)} ${v.moves} 动作 / ${v.sets} 组`).join(' · ')}</p><p class="muted">${plan.estimated&&!d.exerciseIds?`预计约 ${plan.estimated} 分钟（含约 10 分钟热身及组间休息）。`:''}组数为直接训练组数，复合动作还会间接训练其他肌群。按训练表现调整，不要求把时间练满。</p>${plan.entries&&plan.ids.length<6&&Number(state.profile.minutes)>=90?'<p class="notice">当前经验或可用器械限制了动作选择；可在设置中核对器械。不重复同一动作来填满时长。</p>':''}</div>`;}
function displayedWorkoutIds(d,plan){return d.manualOrder?[...(d.exerciseIds||plan.ids)]:orderWorkoutIds(d.exerciseIds||plan.ids,d.trainingPreferences);}
function currentWorkoutIds(){return displayedWorkoutIds(workoutDay(),selectedPrescription());}
function orderControls(id){const ids=currentWorkoutIds(),index=ids.indexOf(id);return `<div class="exercise-order"><span>第 ${index+1} 个动作</span><button data-move-up="${id}" aria-label="上移${esc(catalog[id].name)}" ${index<=0?'disabled':''}>↑ 上移</button><button data-move-down="${id}" aria-label="下移${esc(catalog[id].name)}" ${index===ids.length-1?'disabled':''}>↓ 下移</button></div>`;}
function moveWorkoutExercise(id,step){if(![-1,1].includes(step))return false;const ids=currentWorkoutIds(),from=ids.indexOf(id),to=from+step;if(from<0||to<0||to>=ids.length)return false;[ids[from],ids[to]]=[ids[to],ids[from]];const d=workoutDay();d.manualOrder=true;saveWorkoutSelection(ids);render();return true;}

function saveWorkoutSelection(ids){const d=workoutDay(),p=selectedPrescription();d.exerciseIds=[...ids];d.workoutTitle ||= p.title;d.cycle ||= p.cycle;d.sessionEntries ||= p.entries;save();}
function addWorkoutExercise(id){if(!catalog[id]||!supports(id)||currentWorkoutIds().includes(id))return false;saveWorkoutSelection([...currentWorkoutIds(),id]);return true;}
function removeWorkoutExercise(id){const ids=currentWorkoutIds();if(!ids.includes(id))return false;saveWorkoutSelection(ids.filter(other=>other!==id));return true;}
let addMuscle='胸部';
function availableAdditions(){return Object.keys(catalog).filter(id=>supports(id)&&!currentWorkoutIds().includes(id));}
function replacementOptions(id){const ids=workoutDay().exerciseIds||selectedPrescription().ids;return Object.keys(catalog).filter(other=>other!==id&&catalog[other].muscle===catalog[id]?.muscle&&supports(other)&&!ids.includes(other));}
function replaceExercise(oldId,newId,remember=false){const d=workoutDay(),p=selectedPrescription(),ids=d.exerciseIds||p.ids;if(!ids.includes(oldId)||!replacementOptions(oldId).includes(newId))return false;const oldTarget=exerciseTarget(oldId,d);d.exerciseIds=ids.map(id=>id===oldId?newId:id);if(d.sessionEntries)d.sessionEntries=d.sessionEntries.map(entry=>entry.id===oldId?{...entry,id:newId}:entry);d.workoutTitle ||= p.title;d.targets ||= {};d.targets[newId] ||= {...oldTarget};if(catalog[newId].kind==='cardio'){d.cardioTargets ||= {};d.cardioTargets[newId] ||= cardioTarget(oldId,d);}if(remember&&!isPreview()){state.exerciseReplacements ||= {};state.exerciseReplacements[oldId]=newId;}save();return true;}
function exerciseTarget(id,d=workoutDay()){return d.targets?.[id]||(d.targetSets?{sets:d.targetSets,min:8,max:12}:state.exerciseTargets?.[id]||selectedPrescription().targets?.[id]||defaultExerciseTarget(id));}
function setExerciseTarget(id,sets,min,max){if(!Number.isInteger(sets)||sets<1||sets>10||!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>100||min>max)return false;const target={sets,min,max};workoutDay().targets ||= {};workoutDay().targets[id]=target;if(!isPreview()){state.exerciseTargets ||= {};state.exerciseTargets[id]=target;}save();return true;}
function recordingMode(id){const m=catalog[id];return (m.gear==='无器械'||id==='pullup')?'bodyweight':m.gear==='弹力带'?'band':'weighted';}
function setupLabel(id){return ['push','closepush'].includes(id)?'双脚离墙距离 cm（可选）':recordingMode(id)==='band'?'弹力带阻力 / 规格（可选）':'动作版本 / 难度（可选）';}
function formatStrengthLog(id,l){return recordingMode(id)==='weighted'||l.weight>0?`${l.weight} kg × ${l.reps}`:`${l.reps} 次${l.setup?' · '+esc(l.setup)+(['push','closepush'].includes(id)?' cm 离墙':''):''}`;}
function suggestion(id){const target=exerciseTarget(id);const prev=previous(id);if(id==='assistpull')return {weight:prev?.[1].logs[id].at(-1)?.weight||0,reps:target.min,text:'此处记录机器辅助重量，不是额外负重。辅助越大通常越容易；先选能稳定完成次数的辅助设置，再逐步评估减少辅助。'};if(recordingMode(id)!=='weighted'){const last=prev?.[1].logs[id].at(-1);return {weight:0,reps:Math.max(target.min,Math.min(target.max,last?.reps||target.min)),setup:last?.setup||'',text:`建议 ${target.sets} 组 × ${target.min}–${target.max} 次。${recordingMode(id)==='band'?'记录弹力带规格，不换算成公斤。':'不将体重换算为训练重量。'}先稳定完成次数，再调整动作难度；改变难度后重新评估次数。`};}if(!prev)return {weight:0,reps:target.min,text:`首次记录：建议 ${target.sets} 组 × ${target.min}–${target.max} 次，${target.rir?'保留约 '+target.rir+' 次余力，':''}选择能稳定完成的重量。`};const [day,d]=prev;const list=d.logs[id],last=list.at(-1);const previousTarget=exerciseTarget(id,d);const ready=list.length>=previousTarget.sets&&list.every(x=>x.easy&&x.reps>=previousTarget.min);const topped=ready&&list.every(x=>x.reps>=previousTarget.max);const cycle=selectedPrescription().cycle;const reps=Math.max(target.min,Math.min(target.max,ready?last.reps+1:last.reps));return {weight:last.weight,reps,text:`上次 ${day}：${last.weight} kg × ${last.reps}。${cycle?.deload||cycle?.session==='技术轻练'?'当前为轻练/减量，不自动追求加重。':ready&&last.reps<target.max?'各组均反馈轻松，可在目标范围内尝试 +1 次。':topped?'全部目标组轻松达到次数上限，下次可尝试最小可用重量增量；先确认动作质量。':ready?'保持当前负重，先让所有组稳定达到次数上限。':'先保持重量和次数，稳定动作。'}`};}

function lesson(id){const m=catalog[id];return `<div class="card"><p class="eyebrow">MOVEMENT CLASS</p><h2>${esc(m.name)}</h2><p>${esc(m.muscle)} · ${esc(m.gear)}</p><div class="video-placeholder">▷<p>10–30 秒循环教学 · 授权视频待添加</p></div><ul>${m.cues.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>出现疼痛时停止；不熟悉负重动作时请寻求现场指导。</p></div>`;}
let selectedLesson='squat';
function enhance(body,d){const plan=page==='workout'||page==='lesson'?selectedPrescription():prescription();const at=page==='workout'||page==='lesson'?workoutDate():new Date();const recovery=schedule(at)!=='training'||lightDay(at)||d.rest;d.sleepTarget ||= Number(state.profile.sleepTarget)||7;
if(page==='today'){body=body.replace('FOUNDATION / WEEK 01',`${recovery?'RECOVERY':'FOUNDATION'} / WEEK ${weekNumber()}`);body=body.replace('今天，让习惯开始。',recovery?'今天，好好恢复。':'今天，让习惯开始。');body=body.replace('全身基础训练',esc(plan.title));body=body.replace('3 个动作 · 2 组 / 动作 · 约 15 分钟',`${plan.ids.length} 个动作 · ${plan.ids.every(id=>catalog[id].kind==='cardio')?'按分钟记录':plan.durations?'力量与有氧组合':plan.sets+' 组 / 动作'} · 可用 ${esc(state.profile.minutes)} 分钟（当前为短入门课）`);if(recovery)body=body.replace(/<button class="primary" data-action="workout">.*?<\/button>/,`<button class="primary" data-action="rest">${d.rest?'✓ 已完成恢复任务':'记录轻松活动与恢复'} →</button>`);body=body.replace('昨晚睡得怎么样？',`睡眠目标 ${d.sleepTarget} 小时`);body=body.replace('蛋白质食物',['素食','纯素','蛋奶素'].includes(state.profile.diet)?'豆类 / 豆制品':'蛋白质食物');}
if(page==='path'){const stages=state.profile.goal==='提升心肺与耐力'?['轻松起步','稳定时长','耐力基础','强度调节','长期维持']:state.profile.goal==='灵活性与日常活动能力'?['无痛活动','稳定范围','动作控制','日常迁移','长期维持']:state.profile.goal==='建立运动习惯'?['开始行动','规律打卡','基础能力','稳定习惯','长期维持']:state.profile.goal==='保持健康与精力'?['基础活动','力量与有氧','稳定恢复','综合习惯','长期维持']:['Beginner','Foundation','Strength','Hypertrophy','Advanced'];return `<p class="eyebrow">${esc(state.profile.goal)} / YOUR PATH</p><h1>一步一步，把习惯练成力量。</h1><p class="notice">${!state.profile.scheduleMode&&Number(state.profile.days)>=5?'高频计划包含轻量活动日，不要求每天高强度训练。':''} 可用时间是你的时间预算；计划按全身、上下肢或推拉腿分配；较短时段会轮换肌群。两小时是可用预算，不要求用高强度训练填满。</p><p>${esc(scheduleSummary())} · ${esc(equipmentSummary())} · ${esc(state.profile.minutes)} 分钟</p>${cyclePanel(plan.cycle)}<div class="route">${stages.map((name,i)=>`<div class="path-node"><h3>${i===0?'◉':'🔒'} ${name}</h3><p>${i===0?'当前开放：四周训练周期':'后续阶段，尚未开放'}</p>${i===0?Array.from({length:28},(_,j)=>{const dt=new Date(anchorDate()+'T12:00:00');dt.setDate(dt.getDate()+j);const day=dt.toLocaleDateString('en-CA');const kind=schedule(dt);return `<button type="button" class="route-day" data-open-day="${day}"><span>Week ${Math.floor(j/7)+1} / Day ${j%7+1} · ${day}</span><b>${kind==='pending'?'尚未开始':kind==='recovery'?'🌿 恢复':lightDay(dt)?'🌱 轻量活动':esc(prescription(dt).title)+' · '+esc(prescription(dt).cycle?.deload?'减量':prescription(dt).cycle?.session||'')}</b><small>${points(state.history[day]||{sets:{}})>0?'✓ 已有记录':day===dateKey()?'今天':state.plannedWorkouts?.[day]&&(state.plannedWorkouts[day].exerciseIds||state.plannedWorkouts[day].targets||state.plannedWorkouts[day].cardioTargets)?'已调整 · 查看':'查看 / 调整'}</small></button>`;}).join(''):''}</div>`).join('')}</div><button class="primary" data-action="home">开始今日任务 →</button>`;}
if(page==='workout'){const ids=displayedWorkoutIds(d,plan);return `<p class="eyebrow">${workoutDateKey()} / WEEK ${plan.cycle?.week||weekNumber()} / ${recovery?'恢复日 · 可选轻训练':'训练日'}</p><h1>${esc(d.workoutTitle||plan.title)}</h1>${isPreview()?'<p class="notice">提前查看 / 编辑计划：修改只应用于这个日期，不记完成或 XP。到当天再记录训练。</p>':''}<button data-back-route>← 返回我的路线</button>${isPreview()?'<button data-refresh-future>按当前目标重新生成此日期</button>':''}<p class="muted">当前目标：${esc(state.profile.goal)}${d.planGoal&&d.planGoal!==state.profile.goal?' · 此日期保存于旧目标：'+esc(d.planGoal):''}</p><p>${esc(plan.note||'')}</p><p>${esc(plan.preferenceNote||'')}</p><p class="muted">${d.manualOrder?'当前使用你手动调整的顺序，仅应用于这个日期。':'默认按肌群连续训练，同一肌群主项在前、辅助在后；可用动作旁的上移 / 下移调整。'}</p>${dailyPreferencePanel(d)}${cyclePanel(d.cycle||plan.cycle)}<p class="muted">${esc(plan.selectionInfo||'')} 训练经验：${esc(state.profile.experience||'未设置')} · 器械：${esc(equipmentSummary())}</p><p>${ids.length} 个动作 · 预计 ${plan.estimated||'—'} 分钟 · 可用 ${esc(state.profile.minutes)} 分钟</p>${sessionSummary(ids,d,plan)}<div class="card workout-card"><h3>自定义训练动作</h3><p>按器械筛选，支持添加不同肌群动作。移除不会删除已记录的组。</p><div class="library-filters"><label>先选择肌群<select id="add-muscle">${muscleGroups.map(group=>`<option ${group===addMuscle?'selected':''}>${esc(group)}</option>`).join('')}</select></label><label>再选择动作<select id="add-exercise">${availableAdditions().filter(id=>catalog[id].muscle===addMuscle).map(id=>`<option value="${id}">${esc(catalog[id].name)} · ${esc(catalog[id].gear)}</option>`).join('')||'<option value="">此肌群暂无可添加动作，请核对器械或选择其他肌群</option>'}</select></label></div><button class="primary" data-add-exercise ${availableAdditions().some(id=>catalog[id].muscle===addMuscle)?'':'disabled'}>＋ 添加动作</button><p class="muted">仅调整 ${workoutDateKey()} 的训练。力量动作默认 4 组 × 8–12 次；心肺活动按分钟记录；活动度按组与每侧次数或保持秒数练习，均可自定义。</p></div>${d.exerciseIds?'<p class="notice">此日期使用已保存的训练安排；动作仍可手动调整，未来日期可按当前目标重新生成。</p>':''}<p>${state.profile.goal==='灵活性与日常活动能力'?'轻柔活动，不追求疼痛或极限幅度。':plan.durations?'有氧保持可说话的强度；力量训练按每个动作的休息建议。':'按每个动作的休息建议，先保证动作稳定。'}${recovery?'今天不要求训练，恢复任务同样计入 XP。':''}</p>${ids.map(id=>{if(catalog[id].kind==='cardio')return cardioCard(id,d,plan);const m=catalog[id],hint=suggestion(id),target=exerciseTarget(id,d),logs=d.logs?.[id]||[];return `<section class="card workout-card"><button data-lesson="${id}"><h3>${esc(m.name)} ▷</h3><span class="muted">${esc(m.muscle)} · ${esc(m.gear)}</span></button><button class="remove-exercise" data-remove-exercise="${id}">移除此动作</button>${orderControls(id)}<p class="eyebrow">${esc((d.sessionEntries||plan.entries||[]).find(entry=>entry.id===id)?.label||m.muscle)} · 建议休息 ${(d.sessionEntries||plan.entries||[]).find(entry=>entry.id===id)?.rest||90} 秒</p><details class="target-settings"><summary>替换动作</summary><label>相同肌群 · 可用器械<select id="replace-${id}">${replacementOptions(id).map(other=>`<option value="${other}">${esc(catalog[other].name)} · ${esc(catalog[other].gear)}</option>`).join('')||'<option value="">暂无匹配的替代动作</option>'}</select></label><label class="equipment-choice"><input id="remember-replace-${id}" type="checkbox" ${isPreview()?'disabled':''}>后续计划也优先用这个动作</label><button data-replace="${id}" ${replacementOptions(id).length?'':'disabled'}>确认替换</button><p class="muted">替换后使用新动作自己的训练历史；原动作已记录的组保留在成长记录中。</p></details><p class="muted">${esc(exerciseOrderNote(id))}</p><p>${esc(hint.text)}</p><span class="muted">${logs.length} / ${target.sets} 组 · 建议 ${target.min}–${target.max} 次 / 组 · ${recordingMode(id)==='weighted'?hint.weight+' kg':recordingMode(id)==='band'?'弹力带阻力':'徒手动作'}${target.rir?' · RIR '+target.rir:''}${target.timeAdjusted?' · 已按时间预算缩减组数':''}${target.timeWarning?' · 自定义训练量超过可用时间，请调整':''}</span><details class="target-settings"><summary>自定义组数与次数</summary><div class="set-input"><label>目标组数<input id="target-sets-${id}" type="number" min="1" max="10" value="${target.sets}"></label><label>次数下限<input id="target-min-${id}" type="number" min="1" max="100" value="${target.min}"></label><label>次数上限<input id="target-max-${id}" type="number" min="1" max="100" value="${target.max}"></label></div><button data-save-target="${id}">保存此动作目标</button><button data-reset-target="${id}">恢复 4 组 × 8–12 次</button><p id="target-feedback-${id}" class="muted">${isPreview()?'仅应用于这个日期':'应用于今天和后续训练'}，不修改已记录的组。</p></details><div class="set-input">${recordingMode(id)==='weighted'?`<label>${id==='assistpull'?'辅助重量 kg（越大越容易）':'重量 kg'}<input id="weight-${id}" type="number" required inputmode="decimal" min="0" max="500" step="0.5" value="${hint.weight}"></label>`:`<label>${setupLabel(id)}<input id="setup-${id}" ${['push','closepush'].includes(id)?'type="number" min="0" max="300" step="1"':'type="text" maxlength="80"'} value="${esc(hint.setup||'')}"></label>`}<label>次数<input id="reps-${id}" type="number" required inputmode="numeric" min="1" max="100" value="${hint.reps}"></label><label>完成感受<select id="effort-${id}"><option value="normal">适中 / 较难</option><option value="easy">轻松、动作稳定</option></select></label></div><button class="primary" data-log="${id}" ${isPreview()||logs.length>=target.sets?'disabled':''}>记录一组</button> <button data-remove-log="${id}" ${isPreview()?'disabled':''}>撤回最后一组</button>${logs.map((l,i)=>`<p class="set-row">✓ 第 ${i+1} 组 · ${l.mobilitySets?'1 组活动度':l.minutes?l.minutes+' 分钟':formatStrengthLog(id,l)} · ${l.easy?'轻松':'适中 / 较难'}</p>`).join('')}</section>`;}).join('')}${!ids.length?'<p class="notice">当前没有训练动作，可以添加动作或返回今日任务记录恢复。</p>':''}<p>${trained(d)?'🎉 训练已完成，+30 XP 已计入。':'按实际完成情况记录。'}</p><button class="primary" data-action="home">返回今日任务 →</button>`;}
if(page==='lesson')return lesson(selectedLesson)+`<button class="primary" data-action="workout">返回训练</button>`;
if(page==='learn')return `<p class="eyebrow">MOVEMENT LIBRARY / ${Object.keys(catalog).length} MOVES</p><h1>全身动作课堂</h1><p>覆盖胸、背、肩、手臂、臀腿、小腿与核心。视频待接入。</p><div class="library-filters"><label>肌群<select id="muscle-filter">${['全部',...muscleGroups].map(x=>`<option ${muscleFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><label>器械<select id="gear-filter">${['全部',...new Set(Object.values(catalog).map(m=>m.gear))].map(x=>`<option ${equipmentFilter===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="learn-grid">${Object.entries(catalog).filter(([,m])=>(muscleFilter==='全部'||m.muscle===muscleFilter)&&(equipmentFilter==='全部'||m.gear===equipmentFilter)).map(([id,m])=>`<button class="card" data-lesson="${id}"><div class="illustration">▷</div><p class="eyebrow">${esc(m.muscle)}</p><h3>${esc(m.name)}</h3><p>${esc(m.gear)}</p></button>`).join('')||'<p>这个组合暂无动作，请换一个筛选条件。</p>'}</div>`;

if(page==='progress'){const entries=Object.entries(state.history).sort(([a],[b])=>b.localeCompare(a));return `<p class="eyebrow">TRACKING</p><h1>记录表现，看见进步。</h1><div class="tasks"><div class="card"><p>累计经验</p><div class="stat">${total()} XP</div></div><div class="card"><p>连续活动</p><div class="stat">${streak()} 天</div></div></div><div class="section-head"><h3>体重趋势 · 仅自己可见</h3></div><div class="card"><label>今日体重 kg<input id="bodyweight" type="number" min="20" max="500" step="0.1" value="${d.bodyweight||''}"></label><p>只展示记录，不以减重奖励 XP。</p><div class="trend">${entries.filter(([,v])=>v.bodyweight).reverse().map(([day,v])=>`<div>${day}<b>${v.bodyweight} kg</b></div>`).join('')||'暂无记录'}</div></div><div class="section-head"><h3>训练与生活记录</h3></div>${entries.map(([day,v])=>{const logs=Object.entries(v.logs||{});const volume=logs.reduce((sum,[,sets])=>sum+sets.reduce((n,l)=>n+l.weight*l.reps,0),0);return `<div class="card workout-card"><h3>${day} · ${points(v)} XP</h3><p>训练容量 ${volume} kg · 饮水 ${(v.water*.25).toFixed(2)} L · 睡眠 ${v.sleep} h · ${v.protein?'蛋白质 ✓':'蛋白质未记录'} · ${v.vegetables?'蔬菜 ✓':'蔬菜未记录'}</p>${logs.map(([id,sets])=>`<p>${esc(catalog[id]?.name||id)}：${sets.map(l=>`${l.mobilitySets?'1 组活动度':l.minutes?l.minutes+' 分钟':formatStrengthLog(id,l)}`).join(' / ')}</p>`).join('')}</div>`;}).join('')}`;}
return body;}
function lightDay(at=new Date()){if(state.profile.scheduleMode)return false;return Number(state.profile.days)>=5&&[1,3,5].includes((at.getDay()+6)%7)&&schedule(at)==='training';}
function weekNumber(){return Math.max(1,Math.floor((new Date(dateKey())-new Date(state.startDate||dateKey()))/604800000)+1);}
content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=workoutDay();if(b.dataset.lesson){selectedLesson=b.dataset.lesson;page='lesson';render();}if(b.dataset.log){if(isPreview())return;const id=b.dataset.log,p=selectedPrescription();const weightField=document.querySelector('#weight-'+id),repsField=document.querySelector('#reps-'+id);if((weightField&&weightField.value.trim()==='')||repsField.value.trim()===''){weightField?.reportValidity();repsField.reportValidity();return;}const weight=recordingMode(id)==='weighted'?Number(weightField.value):0,reps=Number(repsField.value);const setupField=document.querySelector('#setup-'+id);if(setupField&&!setupField.checkValidity()) {setupField.reportValidity();return;}const setup=setupField?.value.trim().slice(0,80)||'';if(!Number.isFinite(weight)||weight<0||weight>500||!Number.isInteger(reps)||reps<1||reps>100)return;const recordedTarget=exerciseTarget(id,d);d.targets ||= {};for(const exerciseId of (d.exerciseIds||p.ids)){if(catalog[exerciseId].kind!=='cardio')d.targets[exerciseId] ||= {...exerciseTarget(exerciseId,d)};}d.targets[id] ||= {...recordedTarget};d.exerciseIds ||= p.ids;d.workoutTitle ||= p.title;d.cycle ||= p.cycle;d.sessionEntries ||= p.entries;d.targetSets ||= p.sets;d.logs ||= {};d.logs[id] ||= [];if(d.logs[id].length<exerciseTarget(id,d).sets)d.logs[id].push({weight,reps,setup,easy:document.querySelector('#effort-'+id).value==='easy'});save();render();}if(b.dataset.removeLog&&!isPreview()){d.logs?.[b.dataset.removeLog]?.pop();save();render();}});
content.addEventListener('change',e=>{if(e.target.id==='bodyweight'){if(e.target.value.trim()==='')return;const value=Number(e.target.value);if(Number.isFinite(value)&&value>=20&&value<=500){today().bodyweight=value;save();render();}}});
content.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(!b.dataset.action&&b.dataset.set===undefined&&b.dataset.unset===undefined)return;let d=today();if(b.dataset.set!==undefined)d.sets[b.dataset.set]=Math.min(2,(d.sets[b.dataset.set]||0)+1);if(b.dataset.unset!==undefined)d.sets[b.dataset.unset]=Math.max(0,(d.sets[b.dataset.unset]||0)-1);let a=b.dataset.action;if(a==='workout'){if(page!=='lesson')selectedWorkoutDate=null;page='workout';}if(a==='home'){selectedWorkoutDate=null;page='today';}if(a==='protein'||a==='vegetables')d[a]=!d[a];if(a==='rest')d.rest=!d.rest;if(a==='water')d.water=Math.min(8,d.water+1);if(a==='undo-water')d.water=Math.max(0,d.water-1);save();render();});
content.addEventListener('change',e=>{if(e.target.id==='sleep'){if(e.target.value.trim()==='')return;const value=Number(e.target.value);if(!Number.isFinite(value)||value<0||value>24)return;today().sleep=value;save();render();}});
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{selectedWorkoutDate=null;page=b.dataset.page;render();});
const dialog=document.querySelector('#dialog');const setup=document.querySelector('#setup');
function refreshScheduleForm(){const split=setup.elements.namedItem('split');if(split?.closest)split.closest('label').hidden=['提升心肺与耐力','灵活性与日常活动能力'].includes(setup.elements.namedItem('goal').value);const cycle=setup.elements.scheduleMode?.value==='cycle';document.querySelector('#weekly-settings').hidden=cycle;document.querySelector('#cycle-settings').hidden=!cycle;}
setup.addEventListener('change',e=>{if(e.target.name==='scheduleMode'||e.target.name==='goal')refreshScheduleForm();if(e.target.name==='cyclePreset'&&e.target.value!=='custom'){const [train,rest]=e.target.value.split('/');setup.elements.trainDays.value=train;setup.elements.restDays.value=rest;}if(e.target.name==='trainDays'||e.target.name==='restDays')setup.elements.cyclePreset.value='custom';});
setup.addEventListener('click',e=>{const b=e.target.closest('[data-weekdays]');if(!b)return;document.querySelectorAll('[name=weekdays]').forEach(input=>input.checked=b.dataset.weekdays==='work'?Number(input.value)<5:b.dataset.weekdays==='weekend'?Number(input.value)>=5:false);});
function openSetup(){for(const [k,v] of Object.entries(state.profile)){if(k==='equipment'||k==='weekdays')continue;const field=setup.elements[k];if(field)field.value=k==='place'&&v==='家中 · 无器械'?'家中':k==='diet'&&v==='均衡饮食'?'不限制 / 均衡饮食':k==='diet'&&v==='素食'?'蛋奶素':k==='goal'&&v==='增肌'?'增肌与体型塑造':v;}refreshEquipment(setup.elements.place.value,selectedEquipment());setup.elements.scheduleStart.value ||= anchorDate();document.querySelectorAll('[name=weekdays]').forEach(input=>input.checked=(state.profile.weekdays||[]).map(String).includes(input.value));refreshScheduleForm();dialog.showModal();}
document.querySelector('#profile').onclick=openSetup;
setup.addEventListener('change',e=>{if(e.target.name==='place'){const checked=Array.from(document.querySelectorAll('#equipment-options input:checked'),n=>n.value);refreshEquipment(e.target.value,checked.filter(x=>equipmentOptions(e.target.value).includes(x)));}if(e.target.name==='equipment'){const checked=Array.from(document.querySelectorAll('#equipment-options input:checked'));if(e.target.checked){for(const input of checked)if(input!==e.target&&(e.target.value==='无器械 / 徒手'||input.value==='无器械 / 徒手'))input.checked=false;}}});
document.querySelector('#close').onclick=()=>dialog.close();function generatePlan(){const feedback=document.querySelector('#setup-feedback');feedback.textContent='正在生成路线…';try{const profile={};for(const name of ['name','goal','days','place','experience','diet','mealStyle','dietNotes','sleepTarget','minutes','scheduleMode','cyclePreset','trainDays','restDays','scheduleStart','split']){const field=setup.elements.namedItem(name);profile[name]=field?field.value:'';}profile.name=String(profile.name).trim()||'新朋友';const sleep=Number(profile.sleepTarget);if(profile.sleepTarget.trim()===''||!Number.isFinite(sleep)||sleep<6||sleep>10){feedback.textContent='请填写 6–10 小时之间的睡眠目标。';return;}profile.weekdays=Array.from(document.querySelectorAll('[name=weekdays]:checked'),input=>Number(input.value));if(profile.scheduleMode==='weekly'&&profile.weekdays.length)profile.days=String(profile.weekdays.length);if(profile.scheduleMode==='cycle'&&(!Number.isInteger(Number(profile.trainDays))||Number(profile.trainDays)<1||Number(profile.trainDays)>7||!Number.isInteger(Number(profile.restDays))||Number(profile.restDays)<1||Number(profile.restDays)>7)){feedback.textContent='训练和休息天数请分别输入 1–7 天。';return;}if(profile.scheduleMode&&(!/^\d{4}-\d{2}-\d{2}$/.test(profile.scheduleStart)||!Number.isFinite(Date.parse(profile.scheduleStart+'T00:00:00Z'))||new Date(profile.scheduleStart+'T00:00:00Z').toISOString().slice(0,10)!==profile.scheduleStart)){feedback.textContent='请选择计划开始日期。';return;}if(!profile.goal||!profile.place||(profile.scheduleMode!=='cycle'&&(!Number.isInteger(Number(profile.days))||Number(profile.days)<1||Number(profile.days)>7))||!Number.isFinite(Number(profile.minutes))||Number(profile.minutes)<10||Number(profile.minutes)>180){feedback.textContent='请重新选择目标、地点、每周天数和可用时间。';return;}profile.equipment=Array.from(document.querySelectorAll('#equipment-options input:checked'),input=>input.value).filter(x=>equipmentOptions(profile.place).includes(x));const goalChanged=state.profile.goal!==profile.goal;state.profile=profile;const current=today();if(current.exerciseIds&&(goalChanged||!Object.values(current.logs||{}).some(sets=>sets.length))){delete current.exerciseIds;delete current.workoutTitle;delete current.targetSets;delete current.sessionEntries;delete current.cycle;}state.onboarded=true;today().sleepTarget=sleep;state.startDate ||= dateKey();save();page='path';render();feedback.textContent='路线已生成';dialog.close();}catch(error){feedback.textContent='生成失败：'+(error.message||'未知错误')+'。请把这条提示发给我们。';}}
document.querySelector('#generate-plan').onclick=generatePlan;setup.onsubmit=e=>{e.preventDefault();generatePlan();};render();if(!state.onboarded)openSetup();const runtimeWarning=document.querySelector('#runtime-warning');if(runtimeWarning)runtimeWarning.style.display='none';

// Select existing numeric values so typing replaces them instead of appending.
document.addEventListener('click',event=>{const input=event.target;if(input?.tagName==='INPUT'&&input.type==='number'){input.select();}});
document.addEventListener('focusin',event=>{const input=event.target;if(input?.tagName==='INPUT'&&input.type==='number'){input.select();}});

content.addEventListener('change',e=>{if(e.target.id==='muscle-filter'){muscleFilter=e.target.value;render();}if(e.target.id==='gear-filter'){equipmentFilter=e.target.value;render();}});

content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.saveTarget||b.dataset.resetTarget;if(!id)return;let sets=4,min=8,max=12;if(b.dataset.saveTarget){sets=Number(document.querySelector('#target-sets-'+id).value);min=Number(document.querySelector('#target-min-'+id).value);max=Number(document.querySelector('#target-max-'+id).value);}if(!setExerciseTarget(id,sets,min,max)){document.querySelector('#target-feedback-'+id).textContent='组数需为 1–10；次数需为 1–100 的整数，且下限不能大于上限。';return;}render();});

content.addEventListener('click',e=>{const b=e.target.closest('[data-replace]');if(!b)return;const id=b.dataset.replace,newId=document.querySelector('#replace-'+id).value;const remember=document.querySelector('#remember-replace-'+id).checked;if(replaceExercise(id,newId,remember))render();});

content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-exercise')){if(addWorkoutExercise(document.querySelector('#add-exercise').value))render();}if(b.dataset.removeExercise){if(removeWorkoutExercise(b.dataset.removeExercise))render();}});

content.addEventListener('change',e=>{if(e.target.id==='add-muscle'){addMuscle=e.target.value;render();}});

content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.logCardio||b.dataset.saveCardio;if(!id)return;if(b.dataset.logCardio&&isPreview())return;const field=document.querySelector((b.dataset.logCardio?'#cardio-minutes-':'#cardio-target-')+id);const value=Number(field.value);if(!Number.isInteger(value)||value<1||value>180){document.querySelector('#cardio-feedback-'+id).textContent='请输入 1–180 的整数分钟。';return;}const d=workoutDay(),p=selectedPrescription();d.cardioTargets ||= {};d.cardioTargets[id] ||= p.durations?.[id]||15;for(const exerciseId of (d.exerciseIds||p.ids)){if(catalog[exerciseId].kind==='cardio')d.cardioTargets[exerciseId] ||= p.durations?.[exerciseId]||15;}if(b.dataset.saveCardio)d.cardioTargets[id]=value;else{d.exerciseIds ||= p.ids;d.workoutTitle ||= p.title;d.cycle ||= p.cycle;d.logs ||= {};d.logs[id] ||= [];d.logs[id].push({minutes:value,effort:document.querySelector('#cardio-effort-'+id).value,weight:0,reps:0});}save();render();});

content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openDay)openWorkoutDay(b.dataset.openDay);if(b.hasAttribute('data-back-route')){selectedWorkoutDate=null;page='path';render();}});

setup.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-equipment-all')||b.hasAttribute('data-equipment-clear')){const all=b.hasAttribute('data-equipment-all');document.querySelectorAll('#equipment-options input').forEach(input=>input.checked=all&&input.value!=='无器械 / 徒手');}});

content.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.logMobility||b.dataset.saveMobility;if(!id)return;const d=workoutDay(),p=selectedPrescription();const target=Number(document.querySelector('#mobility-target-'+id).value);if(!Number.isInteger(target)||target<1||target>5){document.querySelector('#mobility-feedback-'+id).textContent='请输入 1–5 组的整数。';return;}d.mobilityTargets ||= {};d.mobilityTargets[id]=target;if(b.dataset.logMobility){if(isPreview())return;d.logs ||= {};d.logs[id] ||= [];if(d.logs[id].filter(l=>l.mobilitySets).length<target){d.exerciseIds ||= p.ids;d.workoutTitle ||= p.title;d.cycle ||= p.cycle;d.logs[id].push({mobilitySets:1,weight:0,reps:0});}}save();render();});

function refreshFuturePlan(){if(!isPreview())return false;state.archivedPlannedWorkouts ||= {};state.archivedPlannedWorkouts[workoutDateKey()] ||= [];if(state.plannedWorkouts?.[workoutDateKey()])state.archivedPlannedWorkouts[workoutDateKey()].push(state.plannedWorkouts[workoutDateKey()]);delete state.plannedWorkouts[workoutDateKey()];workoutDay();save();render();return true;}
content.addEventListener('click',e=>{if(e.target.closest('[data-refresh-future]'))refreshFuturePlan();});

content.addEventListener("click",e=>{if(e.target.closest("[data-apply-daily]"))applyDailyPreferences(document.querySelector("#daily-focus").value,document.querySelector("#daily-count").value);});

content.addEventListener("click",e=>{const up=e.target.closest("[data-move-up]"),down=e.target.closest("[data-move-down]");if(up)moveWorkoutExercise(up.dataset.moveUp,-1);if(down)moveWorkoutExercise(down.dataset.moveDown,1);});
